const frontB64 = $input.first().json.body.front;
const backB64 = $input.first().json.body.back;

const prompt = `Eres un sommelier experto con acceso a bases de datos de vinos. Analiza con detalle TODAS las imágenes de etiqueta proporcionadas y extrae TODA la información posible.

PRIMERO determina si la imagen muestra una botella de vino o una etiqueta de vino. Si NO es una botella/etiqueta de vino, devuelve:
{"is_wine": false}

Si SÍ es una botella/etiqueta de vino, devuelve ÚNICAMENTE un JSON válido con esta estructura exacta (sin backticks, sin texto adicional):
{
  "is_wine": true,
  "nombre": "nombre del vino o marca en la etiqueta",
  "bodega": "nombre del productor o bodega",
  "anada": 2023,
  "region": "región vitivinícola (ej: Ribera del Duero, Rioja, Priorat)",
  "denominacion": "denominación de origen o indicación geográfica (ej: DO Ribera del Duero, IGP Vinos de la Tierra)",
  "uva": "variedad o variedades de uva (ej: Tempranillo, Garnacha, Cabernet Sauvignon)",
  "tipo": "Tinto",
  "alcohol": "14.5%",
  "crianza": "tipo de crianza (ej: Roble, Crianza, Reserva, Gran Reserva, Joven)",
  "descripcion": "descripción breve del vino si aparece en alguna etiqueta, máximo 2 frases",
  "url_bodega": "URL de la bodega SOLO si aparece impresa literalmente en la etiqueta, si no null",
  "temp_servicio": "temperatura de servicio recomendada si aparece (ej: 15-16°C)",
  "contiene": "alérgenos o aditivos relevantes (ej: Contiene sulfitos)",
  "volumen": "volumen de la botella (ej: 750 ml)"
}

Reglas importantes:
- Extrae TODOS los campos de CUALQUIER etiqueta disponible (frontal o trasera), no reserves campos solo para la trasera
- Para 'tipo' usa SOLO uno de: Tinto, Blanco, Rosado, Espumoso, Dulce, Fortificado, Naranja
- Si el color no está explícito, infiere el tipo por el color de la botella o conocimiento del vino
- Para vinos españoles conocidos usa tu conocimiento para completar región/uva/tipo/alcohol aunque no aparezcan en la etiqueta — EXCEPCIÓN: 'url_bodega' NUNCA se completa de memoria ni se infiere a partir del nombre de la bodega (por ejemplo, no generes algo como "bodeganombre.com" solo porque reconoces la bodega). Solo se extrae si el texto de la URL/web aparece impreso literalmente en alguna de las etiquetas
- 'denominacion' puede ser DO, DOCa, DOQ, AOC, IGP, VdT, etc.
- Si hay añada visible úsala; si no, devuelve null
- 'alcohol' aparece habitualmente en la etiqueta trasera o frontal como "X% vol" o "X% alc."
- 'volumen' suele aparecer como "75 cl" o "750 ml"
- 'contiene' suele ser "Contiene sulfitos" u otros alérgenos
- Devuelve null SOLO si genuinamente no puedes encontrar ni inferir el campo (salvo url_bodega, que sigue su propia regla arriba)
- NUNCA inventes datos sobre vinos que no reconoces; en ese caso devuelve null`;

const content = [
  { type: 'text', text: prompt },
  { type: 'image_url', image_url: { url: 'data:image/jpeg;base64,' + frontB64, detail: 'high' } }
];
if (backB64) {
  content.push({ type: 'image_url', image_url: { url: 'data:image/jpeg;base64,' + backB64, detail: 'high' } });
}

return [{ json: {
  model: 'gpt-4o',
  max_tokens: 900,
  messages: [{ role: 'user', content }]
} }];

const raw = $input.first().json.choices?.[0]?.message?.content ?? '';

const cleaned = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/, '').trim();

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch {
  parsed = {};
}

// Si GPT indica que no es un vino, devolver flag inmediatamente
if (parsed.is_wine === false) {
  return [{ json: { is_wine: false } }];
}

return [{ json: {
  is_wine: true,
  nombre:       parsed.nombre       ?? null,
  bodega:       parsed.bodega       ?? null,
  anada:        parsed.anada        ?? null,
  region:       parsed.region       ?? null,
  denominacion: parsed.denominacion ?? null,
  uva:          parsed.uva          ?? null,
  tipo:         parsed.tipo         ?? null,
  alcohol:      parsed.alcohol      ?? null,
  crianza:      parsed.crianza      ?? null,
  descripcion:  parsed.descripcion  ?? null,
  url_bodega:   parsed.url_bodega   ?? null,
  temp_servicio: parsed.temp_servicio ?? null,
  contiene:     parsed.contiene     ?? null,
  volumen:      parsed.volumen      ?? null,
} }];

// F30 — Reindexa los datos de "12 Parsear Vision" (GPT Vision), normalizando cadenas
// vacías a null. Antes fusionaba con datos de un QR leído de la etiqueta trasera
// (pick(vino.X, qr.qr_X)); esa rama se eliminó (ver docs/CHANGELOG.md — el escáner de
// QR ya se había retirado del cliente en V1.3, los QR de etiqueta apuntan casi siempre
// al portal AECOC y no a datos útiles). GPT Vision es ahora la única fuente aquí.
function clean(value) {
  if (value === undefined || value === null) return null
  if (typeof value === 'string' && value.trim() === '') return null
  return value
}

const vino = $('12 Parsear Vision').first().json

return [
  {
    json: {
      nombre: clean(vino.nombre),
      bodega: clean(vino.bodega),
      anada: clean(vino.anada),
      region: clean(vino.region),
      denominacion: clean(vino.denominacion),
      uva: clean(vino.uva),
      tipo: clean(vino.tipo),
      alcohol: clean(vino.alcohol),
      crianza: clean(vino.crianza),
      descripcion: clean(vino.descripcion),
      url_bodega: clean(vino.url_bodega),
      temp_servicio: clean(vino.temp_servicio),
      contiene: clean(vino.contiene),
      volumen: clean(vino.volumen),
    }
  }
]

const wineData = $json;

let imagenUrl = null;

if ($json.image) {
  imagenUrl = $json.image;
}

if (!imagenUrl) {
  const frontB64 = $('01 Recibir Imagen').first().json.body.front;
  imagenUrl = 'data:image/jpeg;base64,' + frontB64;
}

return [{
  json: {
    ...wineData,
    imagen_url: imagenUrl
  }
}];

function clean(value) {
    if (value === undefined || value === null) return null;

    if (typeof value === "string") {
        value = value.trim();

        if (
            value === "" ||
            value.toLowerCase() === "null" ||
            value.toLowerCase() === "undefined"
        ) {
            return null;
        }
    }

    return value;
}

function normalizeAlcohol(value) {

    value = clean(value);

    if (!value) return null;

    value = value
        .replace(",", ".")
        .replace("%", "")
        .replace(/vol/gi, "")
        .trim();

    const number = parseFloat(value);

    return isNaN(number)
        ? null
        : number;
}

function normalizeVolume(value) {

    value = clean(value);

    if (!value) return null;

    value = value.toLowerCase();

    if (value.includes("75")) return 750;

    if (value.includes("750")) return 750;

    if (value.includes("37.5")) return 375;

    if (value.includes("1500")) return 1500;

    return value;
}

function normalizeTipo(value){

    value = clean(value);

    if(!value) return null;

    value=value.toLowerCase();

    if(value.includes("tinto")) return "Tinto";

    if(value.includes("blanco")) return "Blanco";

    if(value.includes("rosado")) return "Rosado";

    if(value.includes("espum")) return "Espumoso";

    if(value.includes("dulce")) return "Dulce";

    if(value.includes("fort")) return "Fortificado";

    if(value.includes("naranja")) return "Naranja";

    return value;
}

function normalizeAnada(value){

    value=clean(value);

    if(!value) return null;

    const year=parseInt(value);

    if(year>=1900 && year<=2100)
        return year;

    return null;

}

// Verificación real: GPT Vision no navega la web, solo reconoce patrones de nombres de
// bodega — antes de aceptar url_bodega comprobamos que la URL responda de verdad (mismo
// patrón que Wine Enrich F8b). Si no responde 2xx/3xx, se descarta en vez de guardar un
// enlace inventado o roto.
async function urlEsAlcanzable(url) {
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET',
      url,
      timeout: 8000,
      simple: false,
      returnFullResponse: true,
    })
    return res.statusCode >= 200 && res.statusCode < 400
  } catch {
    return false
  }
}

const wine=$input.first().json;

let urlBodega = clean(wine.url_bodega);
if (urlBodega && !/^https?:\/\//i.test(urlBodega)) {
  urlBodega = null;
}
if (urlBodega && !(await urlEsAlcanzable.call(this, urlBodega))) {
  urlBodega = null;
}

return [

{

json:{

...wine,

nombre:clean(wine.nombre),

bodega:clean(wine.bodega),

anada:normalizeAnada(wine.anada),

region:clean(wine.region),

denominacion:clean(wine.denominacion),

uva:clean(wine.uva),

tipo:normalizeTipo(wine.tipo),

alcohol:normalizeAlcohol(wine.alcohol),

volumen:normalizeVolume(wine.volumen),

crianza:clean(wine.crianza),

descripcion:clean(wine.descripcion),

url_bodega:urlBodega,

temp_servicio:clean(wine.temp_servicio),

contiene:clean(wine.contiene),

certificaciones:Array.isArray(wine.certificaciones)
? wine.certificaciones
:[],

maridaje:Array.isArray(wine.maridaje)
? wine.maridaje
:[],

imagen_url:clean(wine.imagen_url),

qr_fuente:clean(wine.qr_fuente)

}

}

];
